INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 24001, 401, "アヤネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 2, 0.0, 102301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2.21, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 24002, 402, "アヤネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 102301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 24003, 403, "アヤネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 2, 0.0, 102301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1.99, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 24004, 701, "アサヒ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 1, 0.0, 192201);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2.21, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 24005, 702, "アサヒ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 192201);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3.33, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 24006, 703, "アサヒ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 1, 0.0, 192201);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 24007, 801, "部員３", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 2, 0.0, 192301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2.68, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 24008, 802, "部員３", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 192301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 24009, 803, "部員３", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 2, 0.0, 192301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "やった！", 24010, 501, "", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 1, 0.0, 192501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "勝ったよ！", 24011, 502, "", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 1, 0.0, 192501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "いい調子！", 24012, 503, "", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 1, 0.0, 192501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (5.33, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 24013, 111, "ミサト", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 6, 2, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (6.85, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 24014, 112, "ミサト", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3.0, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 24015, 113, "ミサト", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (6.11, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 24016, 611, "ダイチ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 192401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (6.75, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 24017, 612, "ダイチ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 192401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 24018, 613, "ダイチ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 2, 0.0, 192401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (4.52, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 24019, 211, "ハツネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 1, 0.0, 113401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3.89, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 24020, 212, "ハツネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 1, 0.0, 113401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (13.49, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 24021, 213, "ハツネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 113401);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3.17, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 24022, 311, "カヤ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 106501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (4.42, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 24023, 312, "カヤ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 106501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2.89, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 24024, 313, "カヤ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 6, 1, 0.0, 106501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3.71, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 24025, 421, "アヤネ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 4, 3, 0.0, 102301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (5.1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 24026, 721, "アサヒ", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 1, 0.0, 192201);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (4.34, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 24027, 821, "部員３", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 3, 0.0, 192301);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "いい勝負だったよ\nまたやろうね", 24028, 521, "", 24, 0.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 1, 0.0, 192501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (5.62, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 24029, 101, "ミサト", 24, -360.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (9.58, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 24030, 102, "ミサト", 24, -360.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 24031, 103, "ミサト", 24, -360.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 2, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (9.13, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 24032, 104, "ミサト", 24, -360.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 2, 1, 0.0, 113501);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (8.27, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 24033, 105, "ミサト", 24, -360.0, "2030/12/17 14:59:59", "2020/07/31 12:00:00", 10046, 1, 2, 0.0, 113501);
